{
  "status": "answer",
  "simple_answer": [
    {
      "text": "The Quran commands the payment of the prescribed alms.",
      "source_ids": [
        "Q2:43"
      ],
      "requirement_id": "R1"
    },
    {
      "text": "Shaykh Abdul-Aziz ibn Baz explained that zakah is obligatory on gold when it reaches the threshold.",
      "source_ids": [
        "S83bf0608-c324-c010-7083-b75e9916320f"
      ],
      "requirement_id": "R2"
    }
  ],
  "list": [
    {
      "text": "Zakah must be paid on a wife's gold when it reaches the threshold.",
      "source_ids": [
        "S83bf0608-c324-c010-7083-b75e9916320f"
      ],
      "requirement_id": "R2"
    },
    {
      "text": "Zakah must be paid on a daughter's gold when it reaches the threshold.",
      "source_ids": [
        "S83bf0608-c324-c010-7083-b75e9916320f"
      ],
      "requirement_id": "R2"
    },
    {
      "text": "A person owning money must pay zakah on it even if it is saved for marriage or buying a house.",
      "source_ids": [
        "S4c71789a-80d2-90c8-1a2c-79aa9f791bc8"
      ],
      "requirement_id": "R2"
    }
  ],
  "more_explanation": [
    {
      "heading": "Scholar Explanations",
      "sentences": [
        {
          "text": "Shaykh Muhammad ibn Salih al-Uthaymeen stated that funds owned by an individual are subject to zakah regardless of the intended purpose.",
          "source_ids": [
            "S4c71789a-80d2-90c8-1a2c-79aa9f791bc8"
          ],
          "requirement_id": "R2"
        }
      ]
    }
  ],
  "limit_note": []
}

